import { computed, signal } from '@pyreon/reactivity'
import { For } from '@pyreon/core'
import { LiveRegion, VisuallyHidden } from '@pyreon/a11y'

const ALL = ['Signals', 'Router', 'Hooks', 'Forms', 'Charts']

export function Search() {
  const query = signal('')
  const results = computed(() => ALL.filter((x) => x.toLowerCase().includes(query().toLowerCase())))

  return (
    <div>
      <label>
        <VisuallyHidden>Search packages</VisuallyHidden>
        <input type="search" onInput={(e) => query.set(e.currentTarget.value)} />
      </label>
      <LiveRegion visible>{() => `${results().length} results`}</LiveRegion>
      <ul>
        <For each={results} by={(r) => r}>
          {(r) => <li>{r}</li>}
        </For>
      </ul>
    </div>
  )
}

import { signal } from '@pyreon/reactivity'
import { announce, createA11yId } from '@pyreon/a11y'

export function PasswordField() {
  const hintId = createA11yId('hint')
  const value = signal('')
  const invalid = signal(false)

  const submit = (e: SubmitEvent) => {
    e.preventDefault()
    const bad = value().length < 8
    invalid.set(bad)
    announce(bad ? 'Password needs at least 8 characters' : 'Account created', {
      politeness: bad ? 'assertive' : 'polite',
    })
  }

  return (
    <form onSubmit={submit}>
      <label for="pw">Password</label>
      <input
        id="pw"
        type="password"
        aria-describedby={hintId}
        aria-invalid={() => invalid()}
        onInput={(e) => value.set(e.currentTarget.value)}
      />
      <p id={hintId}>At least 8 characters.</p>
      <button type="submit">Create account</button>
    </form>
  )
}

import { createRouter, RouterProvider, RouterView } from '@pyreon/router'
import { RouteAnnouncer } from '@pyreon/a11y/router'
import { SkipLink } from '@pyreon/a11y'

const Home = () => <h1>Home</h1>
const Billing = () => <h1>Billing</h1>

const router = createRouter({
  routes: [
    { path: '/', component: Home, meta: { title: 'Home' } },
    { path: '/billing', component: Billing, meta: { title: 'Billing' } },
  ],
})

export function App() {
  return (
    <RouterProvider router={router}>
      <SkipLink href="#main">Skip to content</SkipLink>
      <RouteAnnouncer format={(to) => `${to.meta.title ?? to.path} page`} />
      <main id="main">
        <RouterView announceRouteChanges={false} />
      </main>
    </RouterProvider>
  )
}
